
import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Sidebar } from '../../components/feature/Sidebar';
import Header from '../../components/feature/Header';
import Card from '../../components/base/Card';
import Button from '../../components/base/Button';
import Badge from '../../components/base/Badge';
import { inquiryService } from '../../services/inquiryService';
import RecordInquiryDialog from '../../components/feature/RecordInquiryDialog';
import type { User } from '../../types';
import { formatMMDDYYYYOr } from '../../utils/dateFormat';

const InquiriesPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const sourceParam = searchParams.get('source');
  
  const [inquiries, setInquiries] = useState<User[]>([]);
  const [filteredInquiries, setFilteredInquiries] = useState<User[]>([]);
  const [viewStyle, setViewStyle] = useState<'grid' | 'table'>('table');
  const [isLoading, setIsLoading] = useState(true);
  const [isRecordDialogOpen, setIsRecordDialogOpen] = useState(false);

  useEffect(() => {
    fetchInquiries();
  }, []);

  useEffect(() => {
    let filtered = inquiries;
    
    if (sourceParam) {
      filtered = filtered.filter(inquiry => {
        const source = inquirySourceOf(inquiry).toLowerCase();
        if (sourceParam === 'online') {
          return source === 'online' || source === 'website' || source === 'app' || source === '—';
        }
        if (sourceParam === 'phone') {
          return source === 'phone' || source === 'manual' || source === 'call';
        }
        return true;
      });
    }

    const statusParam = searchParams.get('status');
    if (statusParam) {
      filtered = filtered.filter(inquiry => 
        (inquiry.status as string).toLowerCase() === statusParam.toLowerCase()
      );
    }
    
    setFilteredInquiries(filtered);
  }, [inquiries, sourceParam, searchParams]);

  const fetchInquiries = async () => {
    setIsLoading(true);
    try {
      const data = await inquiryService.getNewInquiries();
      setInquiries(data);
    } catch (error) {
      console.error('Error fetching inquiries:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleStatusUpdate = async (userId: string, newStatus: string) => {
    if (!window.confirm(`Are you sure you want to move this inquiry to "${newStatus}"?`)) return;
    
    try {
      await inquiryService.updateInquiryStatus(userId, newStatus);
      fetchInquiries(); // Refresh list
    } catch (error) {
      alert('Failed to update status');
    }
  };

  // Resolves the human-readable inquiry source for a user. Prefers the
  // dedicated `inquiry_source` column but falls back to `data.inquirySource`
  // for rows written before the column existed.
  const inquirySourceOf = (user: User): string => {
    const direct = (user as Record<string, unknown>).inquiry_source;
    if (typeof direct === 'string' && direct.trim()) return direct;
    const blob = (user as Record<string, unknown>).data as Record<string, unknown> | undefined;
    if (blob && typeof blob.inquirySource === 'string' && blob.inquirySource.trim()) {
      return blob.inquirySource;
    }
    return '—';
  };

  const handeArchive = async (userId: string) => {
      if (!window.confirm('Are you sure you want to archive this inquiry?')) return;
      try {
          await inquiryService.archiveInquiry(userId);
          fetchInquiries();
      } catch (error) {
          alert('Failed to archive');
      }
  };

  const getStatusBadge = (status: string) => {
    switch (status?.toLowerCase()) {
      case 'new':
      case 'pending':
      case 'new inquiry':
        return <Badge color="yellow">New</Badge>;
      case 'reviewed':
        return <Badge color="purple">Reviewed</Badge>;
      case 'contacted':
        return <Badge color="blue">Contacted</Badge>;
      case 'follow-up':
        return <Badge color="orange">Follow Up</Badge>;
      case 'consultation scheduled':
        return <Badge color="green">Scheduled</Badge>;
      case 'intake in progress':
        return <Badge color="indigo">Intake</Badge>;
      case 'declined / inactive':
        return <Badge color="red">Inactive</Badge>;
      default:
        return <Badge color="gray">{status}</Badge>;
    }
  };

  return (
    <div className="flex h-screen bg-[#fdf4f6] dark:bg-[#0e0b1a]">
      <Sidebar />
      <div className="flex-1 flex flex-col overflow-hidden">
        <Header />
        
        <main className="flex-1 overflow-y-auto p-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-8">
            <div>
              <h1 className="text-2xl font-bold text-gray-900 dark:text-white">New Inquiries</h1>
              <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">Manage incoming Intended Parent leads.</p>
            </div>
            <div className="flex items-center gap-3">
              <div className="flex bg-gray-100 dark:bg-[#15111f] p-1 rounded-lg">
                <button
                  onClick={() => setViewStyle('grid')}
                  className={`p-2 rounded-md transition-colors cursor-pointer ${
                    viewStyle === 'grid'
                      ? 'bg-white dark:bg-white/5 text-rose-500 dark:text-rose-400 shadow-sm'
                      : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'
                  }`}
                  title="Grid View"
                >
                  <i className="ri-layout-grid-line text-lg"></i>
                </button>
                <button
                  onClick={() => setViewStyle('table')}
                  className={`p-2 rounded-md transition-colors cursor-pointer ${
                    viewStyle === 'table'
                      ? 'bg-white dark:bg-white/5 text-rose-500 dark:text-rose-400 shadow-sm'
                      : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'
                  }`}
                  title="Table View"
                >
                  <i className="ri-table-line text-lg"></i>
                </button>
              </div>
              <Button variant="outline" onClick={fetchInquiries}>
                <i className="ri-refresh-line mr-2"></i>
                Refresh
              </Button>
              <Button onClick={() => setIsRecordDialogOpen(true)}>
                <i className="ri-phone-line mr-2"></i>
                Record Inquiry
              </Button>
            </div>
          </div>

          {isLoading ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {Array.from({ length: 6 }).map((_, i) => (
                <div key={i} className="h-48 bg-gray-100 dark:bg-[#15111f] rounded-xl animate-pulse" />
              ))}
            </div>
          ) : filteredInquiries.length === 0 ? (
            <Card className="p-12 text-center text-gray-500">
              No new inquiries found.
            </Card>
          ) : viewStyle === 'grid' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredInquiries.map((user) => (
                <Card key={user.id} className="hover:shadow-lg transition-shadow">
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-blue-100 dark:bg-blue-900 rounded-full flex items-center justify-center">
                        <i className="ri-user-follow-line text-rose-500 dark:text-rose-400"></i>
                      </div>
                      <div>
                        <h3 className="font-semibold text-gray-900 dark:text-white">
                          {user.firstName} {user.lastName}
                        </h3>
                        <p className="text-xs text-gray-500 dark:text-gray-500">
                          ID: {user.id.split('-')[0]}...
                        </p>
                      </div>
                    </div>
                    <div className="flex flex-col items-end gap-1">
                      {getStatusBadge(user.status as string)}
                    </div>
                  </div>

                  <div className="space-y-2 mb-6">
                    <div className="flex justify-between text-sm">
                      <span className="text-gray-500">Email:</span>
                      <a href={`mailto:${user.email}`} className="text-blue-600 hover:underline truncate ml-2">
                        {user.email}
                      </a>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span className="text-gray-500">Received:</span>
                      <span className="text-gray-900 dark:text-white">
                        {formatMMDDYYYYOr(user.createdAt)}
                      </span>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span className="text-gray-500">Source:</span>
                      <span className="text-gray-900 dark:text-white">
                        {inquirySourceOf(user)}
                      </span>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-2">
                    <Button 
                      size="sm" 
                      color="purple" 
                      variant="outline"
                      onClick={() => handleStatusUpdate(user.id, 'Reviewed')}
                    >
                      <i className="ri-search-line mr-1"></i>
                      Reviewed
                    </Button>
                    <Button 
                      size="sm" 
                      color="blue" 
                      variant="outline"
                      onClick={() => handleStatusUpdate(user.id, 'Contacted')}
                    >
                      <i className="ri-phone-line mr-1"></i>
                      Contacted
                    </Button>
                    <Button 
                      size="sm" 
                      color="green" 
                      onClick={() => handleStatusUpdate(user.id, 'Consultation Scheduled')}
                    >
                      <i className="ri-calendar-check-line mr-1"></i>
                      Schedule
                    </Button>
                    <Button 
                      size="sm" 
                      color="red" 
                      variant="outline"
                      onClick={() => handeArchive(user.id)}
                    >
                      <i className="ri-archive-line mr-1"></i>
                      Archive
                    </Button>
                  </div>
                </Card>
              ))}
            </div>
          ) : (
            <Card>
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead className="bg-rose-50/50 dark:bg-white/5 text-gray-600 dark:text-gray-400 text-xs uppercase">
                    <tr>
                      <th className="px-6 py-3 font-semibold">Name</th>
                      <th className="px-6 py-3 font-semibold">Email</th>
                      <th className="px-6 py-3 font-semibold">Source</th>
                      <th className="px-6 py-3 font-semibold">Date Received</th>
                      <th className="px-6 py-3 font-semibold">Status</th>
                      <th className="px-6 py-3 font-semibold text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                    {filteredInquiries.map((user) => (
                      <tr key={user.id} className="hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
                        <td className="px-6 py-4">
                          <div className="font-medium text-gray-900 dark:text-white">
                            {user.firstName} {user.lastName}
                          </div>
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-600 dark:text-gray-400">
                          <a href={`mailto:${user.email}`} className="text-blue-600 hover:underline">
                            {user.email}
                          </a>
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-600 dark:text-gray-400">
                          {inquirySourceOf(user)}
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-600 dark:text-gray-400">
                          {formatMMDDYYYYOr(user.createdAt)}
                        </td>
                        <td className="px-6 py-4">
                          {getStatusBadge(user.status as string)}
                        </td>
                        <td className="px-6 py-4 text-right space-x-1.5">
                           <Button 
                             size="sm" 
                             color="purple" 
                             variant="outline"
                             title="Mark as Reviewed"
                             onClick={() => handleStatusUpdate(user.id, 'Reviewed')}
                           >
                             <i className="ri-search-line"></i>
                           </Button>
                           <Button 
                             size="sm" 
                             color="blue" 
                             variant="outline"
                             title="Mark as Contacted"
                             onClick={() => handleStatusUpdate(user.id, 'Contacted')}
                           >
                             <i className="ri-phone-line"></i>
                           </Button>
                           <Button 
                             size="sm" 
                             color="orange" 
                             variant="outline"
                             title="Needs Follow Up"
                             onClick={() => handleStatusUpdate(user.id, 'Follow-Up')}
                           >
                             <i className="ri-chat-follow-up-line"></i>
                           </Button>
                           <Button 
                             size="sm" 
                             color="green" 
                             title="Schedule Consultation"
                             onClick={() => handleStatusUpdate(user.id, 'Consultation Scheduled')}
                           >
                             <i className="ri-calendar-check-line"></i>
                           </Button>
                           <Button 
                             size="sm" 
                             color="red" 
                             variant="outline"
                             title="Archive / Decline"
                             onClick={() => handeArchive(user.id)}
                           >
                             <i className="ri-archive-line"></i>
                           </Button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </Card>
          )}

          <RecordInquiryDialog
            isOpen={isRecordDialogOpen}
            onClose={() => setIsRecordDialogOpen(false)}
            onSuccess={fetchInquiries}
          />
        </main>
      </div>
    </div>
  );
};

export default InquiriesPage;
